const link = document.getElementById('indistinguishable-link');
const style = getComputedStyle(link);
const hasUnderline = style.textDecorationLine.includes('underline');
if (!hasUnderline) return false;
link.focus();
const focused = document.activeElement === link;
const rect = link.getBoundingClientRect();
const hasSize = rect.width > 0 && rect.height > 0;
const hasName = link.textContent.trim() === 'comprehensive style guide';
link.blur();
return focused && hasSize && hasName;

